// The Error Trigger gives us the failed execution and the workflow it belonged to.
// Keep the alert short enough to read on a phone.
const j = $input.first().json || {};
const execution = j.execution || {};
const workflow = j.workflow || {};
const error = execution.error || {};

const workflowName = String(workflow.name || execution.workflowId || 'unknown workflow');
const node = String(execution.lastNodeExecuted || 'unknown node');
const message = String(error.message || error.description || 'no message');
const stack = String(error.stack || '').split('\n').slice(0, 6).join('\n');
const executionId = String(execution.id || '');
const mode = String(execution.mode || '');

return [{
  json: {
    subject: 'n8n failure: ' + workflowName + ' — ' + node,
    body: [
      'A workflow failed and needs a look.',
      '',
      'Workflow:  ' + workflowName,
      'Node:      ' + node,
      'Mode:      ' + mode,
      'Execution: ' + executionId,
      'Link:      http://localhost:5678/workflow/' + String(workflow.id || '') + '/executions/' + executionId,
      '',
      'Error: ' + message,
      '',
      stack ? 'Stack (first lines):\n' + stack : '',
      '',
      'Nothing was lost: the invoice workflow keeps its own record and the reply',
      'handler retries unprocessed replies on the next poll.',
    ].join('\n'),
  },
}];
